// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadRobotoMono = makeLoadFont('RobotoMono');

// Module-level font loading
const { fontFamily: robotoMono } = loadRobotoMono();



export type SystemLoadingProps = Record<string, any>;

const SystemLoading: React.FC<SystemLoadingProps> = ({
  backgroundColor = "#020206",
  transparentBackground = false,
  durationInSeconds = 12,
  coreColor = "#00e5ff",
  ringColorPrimary = "#4361ee",
  ringColorSecondary = "#f72585",
  textColor = "#ffffff",
  systemText = "MALLOY TERMINAL // UPLINK",
  complexity = 15,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Responsive scaling factor based on the smallest dimension (typically width for 9:16)
  const s = Math.min(width, height);

  // Parse safe background
  const bgColor = transparentBackground ? undefined : backgroundColor;

  // Animation Timings (leave the end of the video for a "Ready" hold)
  const totalFrames = Math.round(durationInSeconds * fps);
  const holdDurationFrames = Math.min(fps * 1.5, totalFrames * 0.2); // Hold for 1.5s or 20% of video
  const loadDuration = totalFrames - holdDurationFrames;

  // Calculate raw linear progress (0 to 1) and cap it at 1 for the hold phase
  const rawProgress = Math.min(1, frame / loadDuration);
  
  // Apply a cubic easing curve to simulate accelerating speed over time
  const acceleratedTime = Easing.cubic(rawProgress);

  // Calculate percentage based on accelerated time to sync visual speed with the number
  const percentage = Math.floor(acceleratedTime * 100);

  // Status text logic based on progress
  const subStatus = 
    percentage < 15 ? "ESTABLISHING CONNECTION..." :
    percentage < 40 ? "BYPASSING SECURITY PROTOCOLS..." :
    percentage < 70 ? "ACCELERATING SPINDLE DRIVES..." :
    percentage < 95 ? "CALIBRATING CORE MATRIX..." :
    percentage < 100 ? "FINALIZING UPLINK..." :
    "SYSTEM READY";

  // Global 3D Camera/Container movement
  const cameraZ = interpolate(acceleratedTime, [0, 1], [-800, 300]);
  const globalTiltX = interpolate(rawProgress, [0, 1], [15, -10]);
  const globalTiltY = interpolate(rawProgress, [0, 1], [-20, 25]);

  // Core visual logic
  const corePulse = Math.sin(frame * 0.3) * 0.15 + 1;
  const coreScale = (1 + acceleratedTime * 0.8) * corePulse;

  // Deterministic generation of 3D Rings
  const rings = new Array(complexity).fill(0).map((_, i) => {
    const colorIndex = i % 3;
    const color = colorIndex === 0 ? ringColorPrimary : colorIndex === 1 ? ringColorSecondary : coreColor;
    
    const radius = s * 0.12 + (i * s * 0.035); 
    const rotX = random(`rx-${i}`) * 360;
    const rotY = random(`ry-${i}`) * 360;
    const baseRotZ = random(`rz-${i}`) * 360;
    
    // Each ring rotates at a different speed and direction
    const rotationsMax = (random(`rmax-${i}`) * 12 + 4) * (i % 2 === 0 ? 1 : -1);
    const strokeWidth = random(`sw-${i}`) * 4 + 2;
    const dash = random(`dash-${i}`) * 150 + 20;
    const gap = random(`gap-${i}`) * 80 + 20;
    
    return { color, radius, rotX, rotY, baseRotZ, rotationsMax, strokeWidth, dash, gap };
  });

  // Deterministic generation of Data Particles
  const particleCount = complexity * 4;
  const particles = new Array(particleCount).fill(0).map((_, i) => {
    const angle = random(`p-ang-${i}`) * Math.PI * 2;
    // Spread particles in a wide radius
    const pRadius = random(`p-rad-${i}`) * width * 1.2;
    const x = Math.cos(angle) * pRadius;
    const y = Math.sin(angle) * pRadius;
    
    const zOffset = random(`p-z-${i}`) * 2000;
    const speedScale = random(`p-spd-${i}`) * 0.6 + 0.4;
    const size = random(`p-sz-${i}`) * 4 + 2;
    
    return { x, y, zOffset, speedScale, size };
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: robotoMono, overflow: "hidden" }}>
      
      {/* Vignette Layer for depth (only if not transparent) */}
      {!transparentBackground && (
        <div style={{
          position: "absolute",
          inset: 0,
          background: "radial-gradient(circle at center, transparent 30%, rgba(0,0,0,0.85) 120%)",
          zIndex: 1,
          pointerEvents: "none"
        }} />
      )}

      {/* 3D Visualizer Canvas */}
      <div style={{
        position: "absolute",
        top: 0, left: 0, right: 0, bottom: height * 0.2, // Leave space for UI
        perspective: 1000,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        zIndex: 2,
      }}>
        <div style={{
          transformStyle: "preserve-3d",
          transform: `translateZ(${cameraZ}px) rotateX(${globalTiltX}deg) rotateY(${globalTiltY}deg)`,
          width: 0, height: 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}>
          
          {/* Central Glowing Core */}
          <div style={{
            position: "absolute",
            width: s * 0.08,
            height: s * 0.08,
            borderRadius: "50%",
            backgroundColor: "#ffffff",
            boxShadow: `0 0 ${s * 0.03}px ${s * 0.01}px ${coreColor}, 0 0 ${s * 0.08}px ${s * 0.03}px ${coreColor}`,
            transform: `scale(${coreScale})`,
          }} />

          {/* Orbiting 3D Rings */}
          {rings.map((ring, i) => {
            // Apply exponential acceleration to the rotation
            const currentRotZ = ring.baseRotZ + (acceleratedTime * 360 * ring.rotationsMax);
            
            return (
              <div key={`ring-${i}`} style={{
                position: "absolute",
                width: ring.radius * 2,
                height: ring.radius * 2,
                left: -ring.radius,
                top: -ring.radius,
                transformStyle: "preserve-3d",
                transform: `rotateX(${ring.rotX}deg) rotateY(${ring.rotY}deg) rotateZ(${currentRotZ}deg)`,
                transition: "none",
              }}>
                <svg width="100%" height="100%" viewBox="-100 -100 200 200" style={{ overflow: "visible" }}>
                  <circle 
                    cx="0" cy="0" r="95" 
                    fill="none" 
                    stroke={ring.color} 
                    strokeWidth={ring.strokeWidth}
                    strokeDasharray={`${ring.dash} ${ring.gap}`}
                    opacity={0.85}
                  />
                  {/* Subtle inner track for structural feel */}
                  {i % 3 === 0 && (
                     <circle cx="0" cy="0" r="90" fill="none" stroke={ring.color} strokeWidth={0.5} opacity={0.3} />
                  )}
                </svg>
              </div>
            );
          })}

          {/* Flying Data Particles */}
          {particles.map((p, i) => {
            // Move particles towards camera. Travel distance scales with accelerated progress
            const travel = acceleratedTime * 5000 * p.speedScale;
            const rawZ = p.zOffset + travel;
            // Wrap Z depth to loop continuously between -2000 (far back) and 1000 (past camera)
            const wrappedZ = ((rawZ + 2000) % 3000) - 2000;
            
            // Fade in from distance, fade out as it approaches camera
            const opacity = interpolate(wrappedZ, [-2000, -1000, 500, 1000], [0, 0.7, 0.7, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp"
            });
            
            return (
              <div key={`part-${i}`} style={{
                position: "absolute",
                width: p.size,
                height: p.size,
                left: -p.size / 2,
                top: -p.size / 2,
                backgroundColor: coreColor,
                borderRadius: "50%",
                boxShadow: `0 0 4px ${coreColor}`,
                transform: `translate3d(${p.x}px, ${p.y}px, ${wrappedZ}px)`,
                opacity,
                transition: "none",
              }} />
            );
          })}
        </div>
      </div>

      {/* 2D UI Overlay */}
      <div style={{
        position: "absolute",
        bottom: height * 0.08,
        width: "84%",
        left: "8%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        textAlign: "center",
        zIndex: 3,
        color: textColor,
      }}>
        
        {/* Percentage Readout */}
        <h1 style={{ 
          fontSize: s * 0.18, 
          fontWeight: 700, 
          margin: 0,
          lineHeight: 1,
          letterSpacing: "-0.05em",
          textShadow: `0 0 15px ${coreColor}88`,
        }}>
          {percentage}%
        </h1>
        
        {/* Main System Text */}
        <h2 style={{
          fontSize: s * 0.05,
          fontWeight: 600,
          margin: `${s * 0.02}px 0 0 0`,
          letterSpacing: "0.02em",
        }}>
          {systemText}
        </h2>
        
        {/* Dynamic Sub-status */}
        <p style={{
          fontSize: s * 0.035,
          margin: `${s * 0.015}px 0 ${s * 0.04}px 0`,
          opacity: 0.7,
          letterSpacing: "0.05em",
        }}>
          {subStatus}
        </p>
        
        {/* Cyberpunk Progress Bar */}
        <div style={{
          width: "100%",
          height: s * 0.012,
          backgroundColor: "rgba(255, 255, 255, 0.1)",
          borderRadius: s * 0.006,
          position: "relative",
          overflow: "hidden",
        }}>
          <div style={{
            position: "absolute",
            left: 0, top: 0, bottom: 0,
            width: `${percentage}%`,
            backgroundColor: coreColor,
            boxShadow: `0 0 10px ${coreColor}`,
            transition: "none",
          }} />
        </div>
      </div>

      {/* Subtle Terminal Scanlines Overlay */}
      <div style={{
        position: "absolute",
        inset: 0,
        background: `repeating-linear-gradient(
          0deg,
          transparent,
          transparent 2px,
          rgba(0, 0, 0, 0.15) 2px,
          rgba(0, 0, 0, 0.15) 4px
        )`,
        pointerEvents: "none",
        zIndex: 4,
      }} />

    </AbsoluteFill>
  );
};

export default SystemLoading;